import { MeshBasicNodeMaterial } from 'three/webgpu';
import { vec3, mix, uv, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  const group = new Group();
  const cleanupFns = [];

  // Colors
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const colInk = new Color(colors.ink);
  const colPaper = new Color(colors.paper);
  const colAccent = new Color(colors.accent);
  const colSurface = new Color(colors.surface);

  // Card Size Setup (Label Dimensions)
  const width = 2.0;
  const height = 0.8;
  const geom = new PlaneGeometry(width, height);

  // Gradient Material using TSL
  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false
  });

  // TSL Color Shading
  const localUv = uv();
  const grad = localUv.y; // Vertical gradient
  // Smoothly interpolate between surface and ink, accent border accentuation
  const baseColor = mix(vec3(colSurface.r, colSurface.g, colSurface.b), vec3(colInk.r, colInk.g, colInk.b), grad);

  // Highlight border line at bottom
  const borderMask = localUv.y.lessThan(0.05).select(1.0, 0.0);
  const finalColor = mix(baseColor, vec3(colAccent.r, colAccent.g, colAccent.b), borderMask);

  mat.colorNode = finalColor;

  const bgMesh = new Mesh(geom, mat);
  group.add(bgMesh);

  // Texture overlay if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      // Create overlay texture
      const overlayMat = new MeshBasicNodeMaterial({
        map: tex,
        transparent: true,
        opacity: 0.15,
        depthWrite: false
      });
      const overlayMesh = new Mesh(geom, overlayMat);
      overlayMesh.position.z = 0.01;
      group.add(overlayMesh);
    }).catch(err => {
      console.warn('Failed to load card label texture:', err);
    });
  }

  // Text Content
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textStr = textItems[0]?.text ?? 'Collection 3';

  // Render Label text
  const labelText = ctx.fontAtlas.createText(textStr, {
    fontSize: 34,
    color: colors.paper,
    align: 'center'
  });
  labelText.position.set(0, -0.05, 0.02);
  group.add(labelText);

  // Clean-up handler
  group.userData = {
    cleanup: () => {
      geom.dispose();
      mat.dispose();
      cleanupFns.forEach((fn) => fn());
    }
  };

  return group;
}
